function toast(message,type=''){const el=$('#toast');el.textContent=message;el.className=`toast show ${type}`;clearTimeout(el._t);el._t=setTimeout(()=>el.className='toast',3600)}
function escapeHtml(v){return String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));}

async function api(action,payload={},timeout=50000){
 const ctrl=new AbortController(),timer=setTimeout(()=>ctrl.abort(),timeout),start=performance.now();
 try{
  const r=await fetch('/api/gas',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action,...payload}),signal:ctrl.signal});
  const data=await r.json().catch(()=>({ok:false,error:'BAD_JSON',message:'Response bukan JSON'}));
  const ms=Math.round(performance.now()-start);clearTimeout(timer);
  if(!r.ok||data.ok===false){state.apiFailures++;throw Object.assign(new Error(data.message||`HTTP ${r.status}`),{data,status:r.status,ms});}
  state.apiFailures=0;state.backendLive=true;return {...data,_roundTripMs:ms,_upstreamMs:Number(r.headers.get('X-NC-Upstream-Ms')||0)};
 }catch(e){clearTimeout(timer);state.apiFailures++;state.backendLive=false;throw e;}
}

function networkSnapshot(){
 const c=navigator.connection||navigator.mozConnection||navigator.webkitConnection;
 const online=navigator.onLine!==false;const type=(c&&c.effectiveType)||'unknown';const rtt=Number(c&&c.rtt||0);const down=Number(c&&c.downlink||0);
 let mode='online';
 if(!online) mode='offline';
 else if(type==='slow-2g'||type==='2g'||type==='3g') mode='offline-first';
 else if((rtt&&rtt>800)||(down&&down<.8)||state.apiFailures>=2) mode='unstable';
 return {online,type,rtt,down,mode};
}
function updateNetworkUI(){const n=networkSnapshot();state.networkMode=n.mode;const dot=$('#connectionDot'),text=$('#connectionText'),detail=$('#networkDetail'),pill=$('#networkPill');if(!dot)return;dot.className=`status-dot ${n.mode==='online'?'online':n.mode==='offline'?'offline':''}`;text.textContent=n.mode==='online'?'Online':n.mode==='offline'?'Offline':n.mode==='offline-first'?'Offline-first':'Unstable';detail.textContent=`${n.type}${n.rtt?` · RTT ${n.rtt}ms`:''}${n.down?` · ${n.down}Mbps`:''}`;pill.textContent=n.mode==='online'?'Network ready':n.mode==='offline-first'?`${n.type.toUpperCase()} · local save`:n.mode==='unstable'?'Unstable · local save':'Offline · local save';updateQueueBadge();}
function shouldQueue(){return ['offline','offline-first','unstable'].includes(networkSnapshot().mode);}

const EVIDENCE_DB='nc2027-evidence-v1';
const EVIDENCE_STORE='visual-audit-evidence';
function openEvidenceDb(){return new Promise((resolve,reject)=>{if(!('indexedDB'in window))return reject(new Error('IndexedDB unavailable'));const req=indexedDB.open(EVIDENCE_DB,1);req.onupgradeneeded=()=>{const db=req.result;if(!db.objectStoreNames.contains(EVIDENCE_STORE))db.createObjectStore(EVIDENCE_STORE,{keyPath:'key'})};req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error||new Error('IndexedDB open failed'))})}
function idbRequest(req){return new Promise((resolve,reject)=>{req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error||new Error('IndexedDB request failed'))})}
async function evidencePut(record){const db=await openEvidenceDb();try{const tx=db.transaction(EVIDENCE_STORE,'readwrite');await idbRequest(tx.objectStore(EVIDENCE_STORE).put(record));return record}finally{db.close()}}
async function evidenceGet(key){if(!key)return null;const db=await openEvidenceDb();try{return await idbRequest(db.transaction(EVIDENCE_STORE,'readonly').objectStore(EVIDENCE_STORE).get(key))}finally{db.close()}}
async function evidenceDelete(key){if(!key||!('indexedDB'in window))return;try{const db=await openEvidenceDb();try{await idbRequest(db.transaction(EVIDENCE_STORE,'readwrite').objectStore(EVIDENCE_STORE).delete(key))}finally{db.close()}}catch(_){}}
function blobToDataUrl(blob){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(String(r.result||''));r.onerror=()=>reject(r.error||new Error('File read failed'));r.readAsDataURL(blob)})}
function canvasBlob(canvas,type='image/jpeg',quality=.72){return new Promise((resolve,reject)=>canvas.toBlob(b=>b?resolve(b):reject(new Error('Image compression failed')),type,quality))}
async function compressEvidenceCanvas(source,{maxDim=1080,maxBytes=650000}={}){let scale=Math.min(1,maxDim/Math.max(source.width,source.height));let work=document.createElement('canvas');work.width=Math.max(1,Math.round(source.width*scale));work.height=Math.max(1,Math.round(source.height*scale));work.getContext('2d').drawImage(source,0,0,work.width,work.height);let quality=.72,blob=await canvasBlob(work,'image/jpeg',quality);while(blob.size>maxBytes&&quality>.42){quality-=.08;blob=await canvasBlob(work,'image/jpeg',quality)}if(blob.size>maxBytes&&Math.max(work.width,work.height)>800){scale=.78;const smaller=document.createElement('canvas');smaller.width=Math.max(1,Math.round(work.width*scale));smaller.height=Math.max(1,Math.round(work.height*scale));smaller.getContext('2d').drawImage(work,0,0,smaller.width,smaller.height);work=smaller;blob=await canvasBlob(work,'image/jpeg',.5)}return blob}
async function saveVisualEvidenceLocal(originalCanvas,annotatedCanvas){if(!originalCanvas||!annotatedCanvas)return null;const key=`EVD-${uuid()}`;const [originalBlob,annotatedBlob]=await Promise.all([compressEvidenceCanvas(originalCanvas,{maxDim:1080,maxBytes:650000}),compressEvidenceCanvas(annotatedCanvas,{maxDim:1080,maxBytes:650000})]);await evidencePut({key,originalBlob,annotatedBlob,createdAt:new Date().toISOString()});return {key,originalBytes:originalBlob.size,annotatedBytes:annotatedBlob.size}}
async function materializeQueuedPayload(action,payload){if(action!=='submitVisualAudit'||!payload||!payload.evidenceCacheKey)return payload;const pack=await evidenceGet(payload.evidenceCacheKey);if(!pack)return payload;const [original,annotated]=await Promise.all([blobToDataUrl(pack.originalBlob),blobToDataUrl(pack.annotatedBlob)]);return {...payload,evidenceOriginalDataUrl:original,evidenceAnnotatedDataUrl:annotated,evidenceOriginalBytes:pack.originalBlob.size,evidenceAnnotatedBytes:pack.annotatedBlob.size}}
const QKEY='nc2027-offline-queue-v4';
function queueGet(){try{return JSON.parse(localStorage.getItem(QKEY)||'[]')}catch{return[]}}
function queueSet(q){localStorage.setItem(QKEY,JSON.stringify(q));updateQueueBadge()}
function enqueue(action,payload){const q=queueGet();q.push({qid:uuid(),action,payload,createdAt:new Date().toISOString(),retry:0});queueSet(q);return q[q.length-1]}
function updateQueueBadge(){const el=$('#offlineBadge');if(!el)return;const n=queueGet().length;el.textContent=`${n} pending sync`;el.classList.toggle('hidden',n===0)}
async function syncQueue(){if(shouldQueue())return {synced:0,remaining:queueGet().length};let q=queueGet(),synced=0,next=[];for(const item of q){try{const livePayload=await materializeQueuedPayload(item.action,item.payload);await api(item.action,livePayload);if(item.payload&&item.payload.evidenceCacheKey)await evidenceDelete(item.payload.evidenceCacheKey);synced++;}catch(e){item.retry=(item.retry||0)+1;next.push(item);if(e.status===400&&e.data&&e.data.error!=='BUSY')break;}}queueSet(next);if(synced)toast(`${synced} offline submission berhasil disinkronkan.`,'good');return {synced,remaining:next.length}}
async function sendOrQueue(action,payload){if(shouldQueue()){enqueue(action,payload);toast('Jaringan lambat/tidak stabil. Data disimpan lokal dan akan sync otomatis.','warn');return {ok:true,queued:true,message:'Saved locally'};}try{const livePayload=await materializeQueuedPayload(action,payload);const res=await api(action,livePayload);if(payload&&payload.evidenceCacheKey)await evidenceDelete(payload.evidenceCacheKey);return res}catch(e){enqueue(action,payload);toast('Backend belum merespons. Data aman di offline queue.','warn');return {ok:true,queued:true,message:'Saved locally after API failure'}}}

async function login(employeeCode,pin){
 try{const res=await api('loginBootstrap',{employeeCode,pin},55000);state.user=res.user;state.boot=normalizeBoot(res.bootstrap||res);state.backendLive=true;return true;}
 catch(e){const f=FALLBACK_USERS[String(employeeCode).toUpperCase()];if(f&&pin==='1234'){state.user=f;state.boot=normalizeBoot(FALLBACK_BOOT);toast('Backend belum terhubung. Demo berjalan dengan fallback lokal.','warn');return true;}throw e;}
}
function normalizeBoot(b){return {...FALLBACK_BOOT,...b,stats:{...FALLBACK_BOOT.stats,...(b.stats||{})},products:(b.products&&b.products.length?b.products:FALLBACK_BOOT.products),stores:(b.stores&&b.stores.length?b.stores:FALLBACK_BOOT.stores)}}
async function refreshBoot(){if(!state.user)return;try{const b=await api('bootstrap',{userId:state.user.userId},50000);state.boot=normalizeBoot(b);state.backendLive=true;}catch(e){state.boot=state.boot||normalizeBoot(FALLBACK_BOOT);}render();}

