function render(){if(!state.user)return;const r=state.route;if(state.user.role==='NC')renderNC(r);else if(state.user.role==='DATA_ENTRY'&&r==='control')renderControl();else if(state.user.role==='DATA_ENTRY'&&r==='visualreview')renderVisualReviewWorkspace();else if(r==='health')renderHealth();else if(r==='quality')renderQuality();else if(r==='visualdesk')renderVisualDesk();else renderDashboard(state.activeTab);markNav();updateNetworkUI();}

function cardKpi(value,label,delta=''){return `<div class="kpi-card"><div class="value">${escapeHtml(value)}</div><div class="label">${escapeHtml(label)}</div>${delta?`<div class="delta ${delta.startsWith('+')?'positive':delta.startsWith('-')?'negative':''}">${escapeHtml(delta)}</div>`:''}</div>`}
function filterPanel(){return `<aside class="filter-panel"><h3>FILTER BY</h3>${['Period','Region','Area','Channel','TL','NC','Store','Product'].map(x=>`<label class="field"><span>${x}</span><select><option>${x==='Period'?'September 2027':'All'}</option></select></label>`).join('')}<div class="filter-actions"><button class="btn primary">Apply</button><button class="btn secondary">Reset</button></div></aside>`}
function lineChart(data,alt){const vals=data.map(x=>Number(x.value||0)),max=Math.max(...vals,1),min=Math.min(...vals,0),range=Math.max(1,max-min);const pts=vals.map((v,i)=>`${40+i*(520/Math.max(1,vals.length-1))},${210-(v-min)/range*150}`).join(' ');return `<div class="chart-box"><svg viewBox="0 0 600 240" preserveAspectRatio="none">${[60,110,160,210].map(y=>`<line class="chart-grid-line" x1="38" y1="${y}" x2="570" y2="${y}"/>`).join('')}<polyline class="chart-line ${alt?'alt':''}" points="${pts}"/>${vals.map((v,i)=>{const [x,y]=pts.split(' ')[i].split(',');return `<circle class="chart-dot" cx="${x}" cy="${y}" r="4"/>`}).join('')}</svg></div>`}
function barRows(rows,key='achievement'){return `<div class="bars">${rows.map(r=>`<div class="bar-row"><span>${escapeHtml(r.region||r.name)}</span><div class="bar-track"><div class="bar-fill" style="width:${Math.min(100,Number(r[key]||0))}%"></div></div><b>${pct(r[key])}</b></div>`).join('')}</div>`}
function table(headers,rows){return `<div class="table-wrap"><table class="data-table"><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}

