function visualAuditHistory(){
 const live=(state.boot&&Array.isArray(state.boot.visualAudits))?state.boot.visualAudits:[];
 const rows=[...live];
 if(state.ai.lastResult){
  const a=state.ai.lastResult;
  rows.unshift({submissionId:'LOCAL-LATEST',changedAt:new Date().toISOString(),manual:{facing:a.manualFacing,total:a.manualTotal,sos:a.manualSos},ai:{facing:a.aiFacing,total:a.aiTotal,sos:a.aiSos,confidence:a.confidence,osa:a.osa,planogram:a.planogram,posmDetected:a.posm&&a.posm.detected,posmScore:a.posm&&a.posm.score,ocrPrice:a.ocrPrice},comparison:{variance:a.variance,status:Math.abs(a.variance)<=3?'VALIDATED':Math.abs(a.variance)<=5?'WARNING':'ERROR'},evidence:{available:Boolean(state.ai.shelf&&state.ai.overlay),source:'LOCAL_DEVICE'}});
 }
 return rows.length?rows:(FALLBACK_BOOT.visualAudits||[]);
}
function verifiedCell(row,metric){const v=row&&row.verified||null;if(!v)return '<span class="status-badge warn">Pending review</span>';const value=metric==='facing'?fmt(v.facing||0):metric==='total'?fmt(v.total||0):pct(v.sos||0);return `${value}<div class="verified-source">${escapeHtml(v.source||'VERIFIED')}</div>`}
function dualSosChart(audits){
 const rows=[...audits].slice(0,7).reverse();
 if(!rows.length)return '<p class="muted">No visual audit data yet.</p>';
 const manual=rows.map(x=>Number(x.manual&&x.manual.sos||0)),ai=rows.map(x=>Number(x.ai&&x.ai.sos||0));
 const all=[...manual,...ai],max=Math.max(...all,1),min=Math.min(...all,0),range=Math.max(1,max-min);
 const point=(v,i)=>`${42+i*(510/Math.max(1,rows.length-1))},${205-(v-min)/range*145}`;
 const mp=manual.map(point).join(' '),ap=ai.map(point).join(' ');
 return `<div class="comparison-chart"><div class="chart-legend"><span class="legend-manual">Manual</span><span class="legend-ai">AI Detection</span></div><div class="chart-box"><svg viewBox="0 0 600 240" preserveAspectRatio="none">${[60,110,160,210].map(y=>`<line class="chart-grid-line" x1="38" y1="${y}" x2="570" y2="${y}"/>`).join('')}<polyline class="compare-line manual" points="${mp}"/><polyline class="compare-line ai" points="${ap}"/>${manual.map((v,i)=>{const [x,y]=point(v,i).split(',');return `<circle class="compare-dot manual" cx="${x}" cy="${y}" r="4"/>`}).join('')}${ai.map((v,i)=>{const [x,y]=point(v,i).split(',');return `<circle class="compare-dot ai" cx="${x}" cy="${y}" r="4"/>`}).join('')}</svg></div><div class="chart-label-row">${rows.map(x=>`<span>${new Date(x.changedAt).toLocaleDateString('id-ID',{day:'2-digit',month:'short'})}</span>`).join('')}</div></div>`;
}
function latestVisualAudit(){const rows=visualAuditHistory();return rows[0]||null}
function comparisonTableHtml(row){
 if(!row)return '<p class="muted">Belum ada data visual audit.</p>';
 const m=row.manual||{},a=row.ai||{},c=row.comparison||{},status=String(c.status||'REVIEW'),v=row.verified||null;
 const mf=Number(m.facing||0),af=Number(a.facing||0),mt=Number(m.total||0),at=Number(a.total||0),ms=Number(m.sos||0),as=Number(a.sos||0);
 return table(['Metric','Manual','AI Detection','Variance','Verified Result'],[
  ['MJN Product Facing',fmt(mf),fmt(af),`${af-mf>=0?'+':''}${fmt(af-mf)}`,verifiedCell(row,'facing')],
  ['Total Category Facing',fmt(mt),fmt(at),`${at-mt>=0?'+':''}${fmt(at-mt)}`,verifiedCell(row,'total')],
  ['Share of Shelf',pct(ms),pct(as),`${(as-ms)>=0?'+':''}${(as-ms).toFixed(1)} pt`,verifiedCell(row,'sos')],
  ['AI Confidence','-',pct(a.confidence||0),'-',v?`<span class="status-badge good">Reviewed</span>`:`<span class="status-badge ${status==='WARNING'?'warn':status==='ERROR'?'bad':''}">${escapeHtml(status)}</span>`]
 ]);
}
function visualAuditHistoryTable(audits){
 const rows=audits.slice(0,10).map(x=>{const m=x.manual||{},a=x.ai||{},c=x.comparison||{},v=x.verified||null;const st=String(c.status||'REVIEW');const canView=(x.evidence&&x.evidence.available)||x.submissionId==='LOCAL-LATEST';const review=v?`<span class="status-badge good">${escapeHtml(v.source||'VERIFIED')}</span>`:'<span class="status-badge warn">Pending review</span>';return [new Date(x.changedAt).toLocaleString('id-ID',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'}),escapeHtml(x.store||'-'),fmt(m.facing||0),fmt(a.facing||0),pct(m.sos||0),pct(a.sos||0),v?pct(v.sos||0):'-',`${Number(c.variance||0)>=0?'+':''}${Number(c.variance||0).toFixed(1)} pt`,review,canView?`<button class="btn secondary compact evidence-button" data-evidence-id="${escapeHtml(x.submissionId)}">View Evidence</button>`:'<span class="muted">Not stored</span>']});
 return table(['Audit Time','Store','Manual Facing','AI Facing','Manual SOS','AI SOS','Verified SOS','Variance','Review','Evidence'],rows);
}

